let padSize={w:0,h:0},padObserver=null;
function setupPad(){padObserver?.disconnect();let canvas=$('#pad');strokesById[state.id]??=[];const resize=()=>{let r=canvas.getBoundingClientRect();padSize={w:r.width,h:r.height};const d=devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);drawPad()};padObserver=new ResizeObserver(resize);padObserver.observe(canvas);resize();let pointer=null;
 const point=e=>{let r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}};
 canvas.onpointerdown=e=>{if(pointer!==null)return;e.preventDefault();pointer=e.pointerId;canvas.setPointerCapture(pointer);currentStroke={color:pen,points:[point(e)]};strokesById[state.id].push(currentStroke);drawPad()};
 canvas.onpointermove=e=>{if(e.pointerId!==pointer||!currentStroke)return;e.preventDefault();for(const p of (e.getCoalescedEvents?.().length?e.getCoalescedEvents():[e]))currentStroke.points.push(point(p));drawPad()};
 const end=e=>{if(e.pointerId!==pointer)return;if(currentStroke?.points.length>4){mark('wrote');setHint(t('Lovely! Try it once more, or tap Next.','很棒！再寫一次，或按「下一步」。'));}pointer=null;currentStroke=null};canvas.onpointerup=end;canvas.onpointercancel=end;canvas.onlostpointercapture=end;
}
// One stroke path per letter (assets/writing.json, traced from the NIU stroke-order animations) drives the demo, the tracing guide and the copy model, so they always match.
function shapeOf(id){const m=meta[id];if(!m?.strokes)return null;if(!m.lens){m.total=0;m.lens=m.strokes.map(s=>{let L=[0];for(let i=1;i<s.length;i++)L.push(L[i-1]+Math.hypot(s[i][0]-s[i-1][0],s[i][1]-s[i-1][1]));m.total+=L.at(-1);return L})}return m}
function fitShape(m,x,y,w,h){const s=Math.min(w/m.width,h/m.height);return{s,x:x+(w-m.width*s)/2,y:y+(h-m.height*s)/2}}
function curve(ctx,pts,f){const P=pts.map(([x,y])=>[f.x+x*f.s,f.y+y*f.s]);ctx.beginPath();ctx.moveTo(...P[0]);for(let i=1;i<P.length-1;i++)ctx.quadraticCurveTo(P[i][0],P[i][1],(P[i][0]+P[i+1][0])/2,(P[i][1]+P[i+1][1])/2);ctx.lineTo(...P.at(-1));ctx.stroke()}
function drawShape(ctx,m,f,color,width){ctx.lineCap=ctx.lineJoin='round';ctx.strokeStyle=color;ctx.lineWidth=width;m.strokes.forEach(s=>curve(ctx,s,f))}
function startDots(ctx,m,f,r){m.strokes.forEach((s,i)=>{const x=f.x+s[0][0]*f.s,y=f.y+s[0][1]*f.s;ctx.fillStyle='#e5a64a';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();if(m.strokes.length>1){ctx.fillStyle='white';ctx.font=`700 ${r*1.3}px "DM Sans",sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(i+1,x,y+1)}})}
function drawPad(){let canvas=$('#pad');if(!canvas)return;let {w,h}=padSize;if(!w||!h)return;let ctx=canvas.getContext('2d'),d=devicePixelRatio||1,m=shapeOf(state.id);ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);ctx.fillStyle='#fffefa';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#e5e8dc';ctx.lineWidth=1;ctx.setLineDash([5,7]);for(let y of [.22,.50,.78]){ctx.beginPath();ctx.moveTo(0,h*y);ctx.lineTo(w,h*y);ctx.stroke()}ctx.beginPath();ctx.moveTo(w*.5,0);ctx.lineTo(w*.5,h);ctx.stroke();ctx.setLineDash([]);
 if(state.stage==='trace'){if(m){const f=fitShape(m,0,h*.08,w,h*.84);drawShape(ctx,m,f,'#e3e8d6',Math.max(12,f.s*6.5));startDots(ctx,m,f,Math.max(9,f.s*4.5))}else{ctx.fillStyle='#e8ecdf';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`500 ${h*.72}px "Noto Sans Thai Looped", Tahoma, sans-serif`;ctx.fillText(L().char,w*.5,h*.50)}}
 if(state.stage==='copy'){if(m){const f=fitShape(m,12,10,h*.24,h*.26);drawShape(ctx,m,f,'#a3ad91',Math.max(3,f.s*5))}else{ctx.fillStyle='#a3ad91';ctx.font=`500 ${h*.19}px "Noto Sans Thai Looped", Tahoma, sans-serif`;ctx.textAlign='left';ctx.textBaseline='top';ctx.fillText(L().char,14,10)}}
 for(let s of strokesById[state.id]||[]){ctx.strokeStyle=s.color;ctx.lineWidth=Math.max(4,w*.014);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(p.x*w,p.y*h):ctx.moveTo(p.x*w,p.y*h));if(s.points.length===1){ctx.lineTo(s.points[0].x*w+.1,s.points[0].y*h)}ctx.stroke()}}
// Demo timeline: show the start dot, draw each stroke at an even pace with a short pen lift between strokes, hold the finished letter, repeat.
const DEMO_SPEED=.09,DEMO_START=700,DEMO_LIFT=450,DEMO_END=1600;
function demoLength(m){return DEMO_START+m.total/DEMO_SPEED+DEMO_LIFT*(m.strokes.length-1)+DEMO_END}
function demoDistance(m){let t=demoTime-DEMO_START,d=0;if(t<0)return 0;for(const L of m.lens){const len=L.at(-1);if(t<len/DEMO_SPEED)return d+t*DEMO_SPEED;d+=len;t-=len/DEMO_SPEED+DEMO_LIFT;if(t<0)return d}return m.total}
function loadDemo(){demoTime=0;demoPlaying=true;paintDemo()}
function paintDemo(){const canvas=$('#demo'),m=shapeOf(state.id);if(!canvas||!m)return;const ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,f=fitShape(m,W*.08,H*.08,W*.84,H*.84),lw=Math.max(6,f.s*6);ctx.fillStyle='white';ctx.fillRect(0,0,W,H);drawShape(ctx,m,f,'#eceee4',lw);
 let left=demoDistance(m),tip=null;ctx.strokeStyle='#526f43';
 m.strokes.forEach((s,k)=>{const L=m.lens[k],len=L.at(-1);if(left<=0)return;if(left>=len){curve(ctx,s,f);tip=s.at(-1);left-=len;return}let i=1;while(L[i]<left)i++;const r=(left-L[i-1])/(L[i]-L[i-1]||1),p=[s[i-1][0]+(s[i][0]-s[i-1][0])*r,s[i-1][1]+(s[i][1]-s[i-1][1])*r];curve(ctx,[...s.slice(0,i),p],f);tip=p;left=0});
 if(!tip)startDots(ctx,m,f,lw*.9);else if(demoDistance(m)<m.total){ctx.fillStyle='#e5a64a';ctx.beginPath();ctx.arc(f.x+tip[0]*f.s,f.y+tip[1]*f.s,lw*.85,0,7);ctx.fill()}}
let prev=0;function tick(now){let dt=Math.min(100,now-prev);prev=now;if(!document.hidden){if(artPlaying){artTime+=dt;$$('.art-character').forEach(g=>{let a=artTime/800;g.setAttribute('transform',`translate(0 ${Math.sin(a)*3.5}) rotate(${Math.sin(a*.7)*1.4} 160 180)`)})}let m=shapeOf(state.id);if($('#demo')&&m&&demoPlaying){demoTime+=dt;if(demoTime>demoLength(m))demoTime=0;paintDemo()}}requestAnimationFrame(tick)}
